<?php if ($viewMode === 'list'): ?><div class="piece-list"><?php foreach ($pieces as $piece): ?><article><label><?php if ($selectable): ?><input type="checkbox" name="piece_ids[]" value="<?= esc($piece['id']) ?>" <?= $piece['status'] !== 'draft' ? 'disabled' : '' ?>><?php endif ?><a href="<?= site_url('pecas/'.$piece['id']) ?>"><?= esc($piece['title']) ?></a></label><span class="badge"><?= esc($piece['status']) ?></span></article><?php endforeach ?></div>
<?php elseif ($viewMode === 'details'): ?><div class="table-wrap"><table><thead><tr><th>#</th><th>Título</th><th>Tipo</th><th>Palavras-chave</th><th>Status</th></tr></thead><tbody><?php foreach ($pieces as $piece): ?><tr><td><?php if ($selectable): ?><input type="checkbox" name="piece_ids[]" value="<?= esc($piece['id']) ?>" aria-label="Selecionar <?= esc($piece['title']) ?>" <?= $piece['status'] !== 'draft' ? 'disabled' : '' ?>><?php endif ?></td><td><a href="<?= site_url('pecas/'.$piece['id']) ?>"><?= esc($piece['title']) ?></a></td><td><?= esc($piece['type']) ?></td><td><?php if ($piece['keywords']): ?><?php foreach ($piece['keywords'] as $keyword): ?><a class="keyword-link" href="<?= esc($urlFor(['term' => $keyword['id']])) ?>"><?= esc($keyword['label']) ?></a><?php endforeach ?><?php else: ?>Sem palavras-chave<?php endif ?></td><td><span class="badge"><?= esc($piece['status']) ?></span></td></tr><?php endforeach ?></tbody></table></div>
<?php elseif ($viewMode === 'thumbnail'): ?><div class="thumbnail-grid"><?php foreach ($pieces as $piece): ?><?php $fileExtension = mb_strtoupper((string) pathinfo((string) ($piece['original_filename'] ?? ''), PATHINFO_EXTENSION)); ?><?php $fileExtension = $fileExtension !== '' ? $fileExtension : mb_strtoupper((string) $piece['type']); ?><article class="piece-state-<?= esc($piece['display_state']) ?>"><div class="piece-card-flags"><label class="piece-check" title="<?= esc($piece['original_filename'] ?: $piece['title']) ?>"><?php if ($selectable): ?><input type="checkbox" name="piece_ids[]" value="<?= esc($piece['id']) ?>" aria-label="Selecionar <?= esc($piece['title']) ?>" <?= $piece['status'] !== 'draft' ? 'disabled' : '' ?>><?php endif ?><span class="file-extension"><?= esc($fileExtension) ?></span></label><span class="access-badge"><?php if ($piece['display_state_locked']): ?><span aria-hidden="true">🔒</span> <?php endif ?><?= esc($piece['display_state_label']) ?></span></div><a href="<?= site_url('pecas/'.$piece['id']) ?>"><img src="<?= site_url('pecas/'.$piece['id'].'/miniatura') ?>" alt="" width="640" height="360" loading="lazy"><strong><?= esc($piece['title']) ?></strong></a></article><?php endforeach ?></div>
<?php else: ?><div class="card-grid"><?php foreach ($pieces as $piece): ?><?php $fileExtension = mb_strtoupper((string) pathinfo((string) ($piece['original_filename'] ?? ''), PATHINFO_EXTENSION)); ?><?php $fileExtension = $fileExtension !== '' ? $fileExtension : mb_strtoupper((string) $piece['type']); ?><article class="card piece-card piece-state-<?= esc($piece['display_state']) ?>"><div class="piece-card-flags"><label class="piece-check" title="<?= esc($piece['original_filename'] ?: $piece['title']) ?>"><?php if ($selectable): ?><input type="checkbox" name="piece_ids[]" value="<?= esc($piece['id']) ?>" aria-label="Selecionar <?= esc($piece['title']) ?>" <?= $piece['status'] !== 'draft' ? 'disabled' : '' ?>><?php endif ?><span class="file-extension"><?= esc($fileExtension) ?></span></label><span class="access-badge"><?php if ($piece['display_state_locked']): ?><span aria-hidden="true">🔒</span> <?php endif ?><?= esc($piece['display_state_label']) ?></span></div><a class="piece-thumbnail" href="<?= site_url('pecas/'.$piece['id']) ?>" aria-label="Abrir <?= esc($piece['title']) ?>"><img src="<?= site_url('pecas/'.$piece['id'].'/miniatura') ?>" alt="" width="640" height="360" loading="lazy"></a><div class="piece-card-content"><h3><a href="<?= site_url('pecas/'.$piece['id']) ?>"><?= esc($piece['title']) ?></a></h3><div class="piece-keywords" aria-label="Palavras-chave"><?php if ($piece['keywords']): ?><?php foreach ($piece['keywords'] as $keyword): ?><a href="<?= esc($urlFor(['term' => $keyword['id']])) ?>"><?= esc($keyword['label']) ?></a><?php endforeach ?><?php else: ?><span class="no-keywords">Sem palavras-chave</span><?php endif ?></div></div></article><?php endforeach ?></div><?php endif ?>
